function validate([word, k]) {
  if (word.length < 5 || word.length > 200000) return 'word needs 5 to 200,000 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses only lowercase English letters.';
  if (!Number.isInteger(k) || k < 0 || k > word.length - 5) return 'k is between 0 and word.length - 5.';
  return null;
}

