function countOfSubstrings(word, k) {
  const isVowel = (ch) => 'aeiou'.includes(ch);

  // Substrings that hold all five vowels and at least `need` consonants.
  const atLeast = (need) => {
    const vowelCount = new Map();
    let consonants = 0;
    let left = 0;
    let total = 0;
    for (let right = 0; right < word.length; right++) {
      const ch = word[right];
      if (isVowel(ch)) {
        vowelCount.set(ch, (vowelCount.get(ch) ?? 0) + 1);
      } else {
        consonants++;
      }
      while (vowelCount.size === 5 && consonants >= need) {
        const out = word[left];
        if (isVowel(out)) {
          vowelCount.set(out, vowelCount.get(out) - 1);
          if (vowelCount.get(out) === 0) {
            vowelCount.delete(out);
          }
        } else {
          consonants--;
        }
        left++;
      }
      total += left;
    }
    return total;
  };

  return atLeast(k) - atLeast(k + 1);
}

