function countOfSubstrings(word, k) {
  let count = 0;
  for (let start = 0; start < word.length; start++) {
    const vowelsSeen = new Set();
    let consonants = 0;
    for (let end = start; end < word.length; end++) {
      if ('aeiou'.includes(word[end])) vowelsSeen.add(word[end]);
      else consonants++;
      if (consonants > k) break;
      if (consonants === k && vowelsSeen.size === 5) count++;
    }
  }
  return count;
}

