function generate(rand, size) {
  const vowels = 'aeiou';
  const consonantPool = size === 'large' ? 'bcdfghjklmnpqrstvwxyz' : 'bqz';
  const n = size === 'large' ? 10000 : 5 + Math.floor(rand() * 12);
  // Lean toward vowels so that windows holding all five are common.
  const vowelShare = 0.5 + rand() * (size === 'large' ? 0.3 : 0.4);
  let word = '';
  for (let i = 0; i < n; i++) {
    word += rand() < vowelShare ? vowels[Math.floor(rand() * 5)] : consonantPool[Math.floor(rand() * consonantPool.length)];
  }
  const most = n - 5;
  let k;
  if (size === 'large') k = Math.floor(rand() * 60);
  else k = rand() < 0.8 ? Math.min(most, Math.floor(rand() * 4)) : Math.floor(rand() * (most + 1));
  return [word, k];
}
